// ChatMessages.jsx
import React, { useEffect, useRef, useState } from "react";
import toast from "react-hot-toast";

/**
 * Parses structured text generated by Chaos Mode into rich visual card data.
 */
const parseChaosMessage = (text) => {
  if (!text || typeof text !== "string") return null;

  // 1. WOULD_YOU_RATHER
  if (text.includes("WOULD YOU RATHER") || text.includes("Would You Rather")) {
    const lines = text.split("\n").map((l) => l.trim()).filter(Boolean);
    const options = [];
    let prompt = "What do you choose?";

    for (const line of lines) {
      if (line.startsWith("•") || line.startsWith("-") || line.startsWith("*")) {
        options.push(line.replace(/^[•\-\*]\s*/, ""));
      } else if (line.includes("?") || line.toLowerCase().includes("choose")) {
        prompt = line;
      }
    }

    if (options.length >= 2) {
      return {
        type: "WOULD_YOU_RATHER",
        title: "Would You Rather",
        icon: "🤔",
        options,
        prompt,
      };
    }
  }

  // 2. DEBATE
  if (text.includes("DEBATE")) {
    const lines = text.split("\n").map((l) => l.trim()).filter(Boolean);
    let topic = "";
    let sideA = "";
    let sideB = "";
    for (const line of lines) {
      if (line.toLowerCase().includes("topic:")) {
        topic = line.replace(/^[^:]*:\s*/, "").replace(/^["']|["']$/g, "");
      } else if (line.includes("Side A:") || line.includes("🟢")) {
        sideA = line.replace(/^[^:]*:\s*/, "");
      } else if (line.includes("Side B:") || line.includes("🔵")) {
        sideB = line.replace(/^[^:]*:\s*/, "");
      }
    }
    if (topic && sideA && sideB) {
      return {
        type: "DEBATE",
        title: "Debate",
        icon: "⚔️",
        topic,
        sideA,
        sideB,
      };
    }
  }

  // 3. QUIZ
  if (text.includes("QUICK QUIZ") || text.includes("Quick Quiz")) {
    const lines = text.split("\n").map((l) => l.trim()).filter(Boolean);
    let question = "";
    const options = [];
    for (const line of lines) {
      if (/^[A-D]\)/i.test(line)) {
        options.push(line);
      } else if (
        !line.toUpperCase().includes("QUIZ") &&
        !line.includes("Drop your guess")
      ) {
        if (!question) question = line;
      }
    }
    if (options.length >= 2) {
      return {
        type: "QUIZ",
        title: "Quick Quiz",
        icon: "🧠",
        question: question || "Can you guess the right answer?",
        options,
      };
    }
  }

  // 4. ROAST
  if (text.includes("ROAST BATTLE") || text.includes("Roast Battle")) {
    const content = text
      .replace(/^.*ROAST BATTLE:[^\n]*\n?/i, "")
      .replace(/Your turn.*$/i, "")
      .replace(/^["']|["']$/g, "")
      .trim();
    if (content) {
      return {
        type: "ROAST",
        title: "Roast Battle",
        icon: "🔥",
        content,
      };
    }
  }

  // 5. RANDOM_QUESTION
  if (text.includes("Random Question")) {
    const content = text.replace(/^.*Random Question:[^\n]*\n?/i, "").trim();
    if (content) {
      return {
        type: "RANDOM_QUESTION",
        title: "Random Question",
        icon: "🤭",
        content,
      };
    }
  }

  // 6. ICEBREAKER
  if (text.includes("Icebreaker")) {
    const content = text.replace(/^.*Icebreaker:[^\n]*\n?/i, "").trim();
    if (content) {
      return {
        type: "ICEBREAKER",
        title: "Icebreaker",
        icon: "💬",
        content,
      };
    }
  }

  // 7. CHALLENGE
  if (text.includes("Chaos Challenge")) {
    const content = text.replace(/^.*Chaos Challenge:[^\n]*\n?/i, "").trim();
    if (content) {
      return {
        type: "CHALLENGE",
        title: "Random Challenge",
        icon: "🎯",
        content,
      };
    }
  }

  return null;
};

const ChatMessages = ({
  messages,
  userDetails,
  selectedUserId,
  selectedGroupId = null,
  onDeleteMessageForMe,
  onUnsendMessage,
  onReply,
  onSayHi,
}) => {
  const messagesContainerRef = useRef(null);
  const messagesEndRef = useRef(null);
  const [activeMenuId, setActiveMenuId] = useState(null);
  const [unsendTarget, setUnsendTarget] = useState(null);
  const [deleteTarget, setDeleteTarget] = useState(null);
  const [highlightedMessageId, setHighlightedMessageId] = useState(null);
  const longPressTimerRef = useRef(null);

  // Close menus and dialogs on Escape key
  useEffect(() => {
    const handleKeyDown = (e) => {
      if (e.key === "Escape") {
        setActiveMenuId(null);
        setUnsendTarget(null);
        setDeleteTarget(null);
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, []);

  const scrollToBottom = (behavior = "smooth") => {
    const container = messagesContainerRef.current;
    if (container) {
      container.scrollTo({
        top: container.scrollHeight,
        behavior,
      });
    }
    if (messagesEndRef.current) {
      messagesEndRef.current.scrollIntoView({ behavior, block: "end" });
    }
  };

  // Scroll to bottom on messages change
  useEffect(() => {
    scrollToBottom("smooth");
    // Ensure scroll reaches the end after any card or layout reflow
    const timer = setTimeout(() => {
      scrollToBottom("smooth");
    }, 120);
    return () => clearTimeout(timer);
  }, [messages]);

  const formatTime = (dateStr) => {
    if (!dateStr) return "";
    try {
      const date = new Date(dateStr);
      if (isNaN(date.getTime())) return "";
      return date.toLocaleTimeString([], {
        hour: "2-digit",
        minute: "2-digit",
      });
    } catch {
      return "";
    }
  };

  const handleTouchStart = (msgKey) => {
    longPressTimerRef.current = setTimeout(() => {
      setActiveMenuId(msgKey);
    }, 500);
  };

  const handleTouchEnd = () => {
    if (longPressTimerRef.current) {
      clearTimeout(longPressTimerRef.current);
      longPressTimerRef.current = null;
    }
  };

  const getQuoteSenderName = (replyObj) => {
    if (!replyObj) return "Message";
    const replySenderId = (replyObj.sender?._id || replyObj.sender)?.toString();
    if (userDetails?._id && replySenderId === String(userDetails._id)) {
      return "You";
    }
    if (replyObj.sender?.firstName) {
      return replyObj.sender.firstName;
    }
    if (replyObj.sender?.username) {
      return replyObj.sender.username;
    }
    return "User";
  };

  const getQuoteContent = (replyObj) => {
    if (!replyObj) return "Original message unavailable";
    if (replyObj.isUnsent) return "Message unsent";
    if (replyObj.isDeletedForMe) return "Message unavailable";
    if (!replyObj.text) return "Original message unavailable";
    return replyObj.text;
  };

  const handleScrollToMessage = (targetId) => {
    if (!targetId) return;
    const targetElement = document.getElementById(`msg-${targetId}`);
    if (targetElement) {
      targetElement.scrollIntoView({ behavior: "smooth", block: "center" });
      setHighlightedMessageId(targetId);
      setTimeout(() => {
        setHighlightedMessageId((curr) => (curr === targetId ? null : curr));
      }, 1500);
    } else {
      toast("Original message is unavailable in view", { icon: "ℹ️" });
    }
  };

  const handleOptionClick = (message, optionText) => {
    if (onReply) onReply(message);
    const inputEl = document.getElementById("chat-message-input");
    if (inputEl) {
      inputEl.focus();
    }
  };

  const hasActiveChat = Boolean(selectedUserId || selectedGroupId);

  const renderBubbleContent = (message, isMine) => {
    const chaosCard = parseChaosMessage(message.text);

    if (chaosCard) {
      // 1. WOULD_YOU_RATHER Card
      if (chaosCard.type === "WOULD_YOU_RATHER") {
        return (
          <div className="flex flex-col gap-2.5 py-1 min-w-[240px] max-w-full select-text text-left">
            <div className="flex items-center gap-2 border-b border-purple-200/60 pb-2">
              <span className="text-xl">🤔</span>
              <div className="flex items-center gap-1.5 flex-wrap">
                <span className="text-[10px] font-extrabold uppercase tracking-wider text-purple-700 bg-purple-100 px-2 py-0.5 rounded-full border border-purple-200">
                  Would You Rather ✨
                </span>
                <span className="text-[10px] text-plum-500 font-semibold">
                  Sweet Chaos
                </span>
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 pt-0.5">
              <button
                type="button"
                onClick={() => handleOptionClick(message, chaosCard.options[0])}
                className="p-3 rounded-2xl bg-gradient-to-br from-purple-50 to-pink-50 hover:from-purple-100 hover:to-pink-100 border border-purple-200 hover:border-purple-300 hover:shadow-sweet transition-all text-left flex flex-col justify-center active:scale-98 group/opt focus:outline-none"
                title="Tap to answer with Option A"
              >
                <div className="flex items-center justify-between text-[10px] uppercase font-bold text-purple-600 mb-1">
                  <span>Option A</span>
                  <span className="text-xs group-hover/opt:translate-x-0.5 transition-transform">
                    👈
                  </span>
                </div>
                <span className="text-xs sm:text-sm font-bold text-plum-900 leading-snug">
                  {chaosCard.options[0]}
                </span>
              </button>

              <button
                type="button"
                onClick={() => handleOptionClick(message, chaosCard.options[1])}
                className="p-3 rounded-2xl bg-gradient-to-br from-pink-50 to-rose-50 hover:from-pink-100 hover:to-rose-100 border border-pink-200 hover:border-pink-300 hover:shadow-sweet transition-all text-left flex flex-col justify-center active:scale-98 group/opt focus:outline-none"
                title="Tap to answer with Option B"
              >
                <div className="flex items-center justify-between text-[10px] uppercase font-bold text-pink-600 mb-1">
                  <span>Option B</span>
                  <span className="text-xs group-hover/opt:translate-x-0.5 transition-transform">
                    👈
                  </span>
                </div>
                <span className="text-xs sm:text-sm font-bold text-plum-900 leading-snug">
                  {chaosCard.options[1]}
                </span>
              </button>
            </div>

            <div className="flex items-center justify-between text-[11px] text-plum-600 pt-1 font-medium border-t border-purple-100/60">
              <span className="font-semibold">{chaosCard.prompt}</span>
              <span className="text-[10px] text-chatora-pink font-bold">
                Tap choice to reply 💬
              </span>
            </div>
          </div>
        );
      }

      // 2. DEBATE Card
      if (chaosCard.type === "DEBATE") {
        return (
          <div className="flex flex-col gap-2 py-1 min-w-[240px] max-w-full text-left">
            <div className="flex items-center gap-2 border-b border-emerald-200/60 pb-1.5">
              <span className="text-lg">⚔️</span>
              <span className="text-[10px] font-extrabold uppercase tracking-wider text-emerald-700 bg-emerald-100 px-2 py-0.5 rounded-full border border-emerald-200">
                Debate Showdown 🔥
              </span>
            </div>
            <p className="font-bold text-xs sm:text-sm text-plum-900 leading-snug">
              "{chaosCard.topic}"
            </p>
            <div className="space-y-1.5 text-xs pt-1">
              <button
                type="button"
                onClick={() => handleOptionClick(message, chaosCard.sideA)}
                className="w-full text-left p-2.5 rounded-xl bg-emerald-50 hover:bg-emerald-100 border border-emerald-200 text-emerald-950 transition-colors focus:outline-none"
              >
                <span className="font-bold text-emerald-700 mr-1.5">🟢 Side A:</span>
                <span>{chaosCard.sideA}</span>
              </button>
              <button
                type="button"
                onClick={() => handleOptionClick(message, chaosCard.sideB)}
                className="w-full text-left p-2.5 rounded-xl bg-sky-50 hover:bg-sky-100 border border-sky-200 text-sky-950 transition-colors focus:outline-none"
              >
                <span className="font-bold text-sky-700 mr-1.5">🔵 Side B:</span>
                <span>{chaosCard.sideB}</span>
              </button>
            </div>
          </div>
        );
      }

      // 3. QUIZ Card
      if (chaosCard.type === "QUIZ") {
        return (
          <div className="flex flex-col gap-2 py-1 min-w-[240px] max-w-full text-left">
            <div className="flex items-center gap-2 border-b border-amber-200/60 pb-1.5">
              <span className="text-lg">🧠</span>
              <span className="text-[10px] font-extrabold uppercase tracking-wider text-amber-700 bg-amber-100 px-2 py-0.5 rounded-full border border-amber-200">
                Quick Quiz 🎯
              </span>
            </div>
            <p className="font-bold text-xs sm:text-sm text-plum-900 leading-snug">
              {chaosCard.question}
            </p>
            <div className="grid grid-cols-1 gap-1.5 pt-1">
              {chaosCard.options.map((opt, idx) => (
                <button
                  key={idx}
                  type="button"
                  onClick={() => handleOptionClick(message, opt)}
                  className="w-full text-left p-2 rounded-xl bg-cream-50 hover:bg-cream-100 border border-border-subtle text-plum-900 text-xs font-medium transition-colors flex items-center gap-2 focus:outline-none"
                >
                  <span className="w-5 h-5 rounded-full bg-cream-200 border border-border-subtle flex items-center justify-center font-bold text-[10px] text-plum-700 flex-shrink-0">
                    {opt.substring(0, 1)}
                  </span>
                  <span>{opt.substring(2).trim() || opt}</span>
                </button>
              ))}
            </div>
          </div>
        );
      }

      // 4. ROAST Card
      if (chaosCard.type === "ROAST") {
        return (
          <div className="flex flex-col gap-1.5 py-1 text-left min-w-[220px]">
            <div className="flex items-center gap-2 border-b border-rose-200/60 pb-1.5">
              <span className="text-lg">🔥</span>
              <span className="text-[10px] font-extrabold uppercase tracking-wider text-rose-600 bg-rose-100 px-2 py-0.5 rounded-full border border-rose-200">
                Roast Battle
              </span>
            </div>
            <p className="text-xs sm:text-sm font-semibold text-plum-900 italic leading-relaxed pt-1">
              "{chaosCard.content}"
            </p>
            <span className="text-[10px] text-rose-500 font-bold self-end mt-1">
              Your turn 😉
            </span>
          </div>
        );
      }

      // 5. General Chaos Cards (Random Question, Icebreaker, Challenge)
      return (
        <div className="flex flex-col gap-1.5 py-1 text-left min-w-[220px]">
          <div className="flex items-center gap-2 border-b border-border-subtle pb-1.5">
            <span className="text-lg">{chaosCard.icon}</span>
            <span className="text-[10px] font-extrabold uppercase tracking-wider text-chatora-pink bg-chatora-pinkLight px-2 py-0.5 rounded-full border border-chatora-pink/20">
              {chaosCard.title}
            </span>
          </div>
          <p className="text-xs sm:text-sm font-semibold text-plum-900 leading-relaxed pt-1">
            {chaosCard.content}
          </p>
        </div>
      );
    }

    // Standard plain text message bubble
    return <p className="whitespace-pre-wrap">{message.text}</p>;
  };

  return (
    <div
      ref={messagesContainerRef}
      className="w-full flex-1 min-h-0 overflow-y-auto overscroll-contain px-3 sm:px-6 md:px-8 py-4 relative select-text"
    >
      {/* Click outside backdrop for message action menus */}
      {activeMenuId && (
        <div
          className="fixed inset-0 z-30"
          onClick={() => setActiveMenuId(null)}
        ></div>
      )}

      {hasActiveChat && (
        <div className="flex flex-col gap-3.5">
          {(Array.isArray(messages) ? messages : []).map((message, index) => {
            const senderId = (message.sender?._id || message.sender)?.toString();
            const isMine = userDetails?._id
              ? senderId === String(userDetails._id)
              : false;
            const messageKey = message._id || message.id || `msg-${index}`;
            const timeStr = formatTime(message.createdAt);
            const isMenuOpen = activeMenuId === messageKey;
            const isUnsent = Boolean(message.isUnsent);
            const isHighlighted = highlightedMessageId === messageKey;
            const isChaos = !isUnsent && Boolean(parseChaosMessage(message.text));

            // Group sender header: show sender name if group and not mine and not same as previous
            const prevMessage = index > 0 ? messages[index - 1] : null;
            const prevSenderId = prevMessage
              ? (prevMessage.sender?._id || prevMessage.sender)?.toString()
              : null;
            const showSenderHeader =
              Boolean(selectedGroupId) &&
              !isMine &&
              (!prevMessage || prevSenderId !== senderId);

            const senderDisplayName =
              message.sender?.firstName ||
              message.sender?.username ||
              "Member";

            return (
              <div
                key={messageKey}
                id={`msg-${messageKey}`}
                className={`flex flex-col group transition-all duration-300 rounded-3xl p-1 ${
                  isHighlighted
                    ? "ring-2 ring-chatora-pink bg-chatora-pinkLight shadow-sweet-pink"
                    : ""
                } ${isMine ? "items-end" : "items-start"}`}
              >
                {showSenderHeader && (
                  <span className="text-[11px] font-bold text-chatora-pink mb-1 px-1">
                    {senderDisplayName}
                  </span>
                )}
                <div
                  className={`flex items-center gap-2 max-w-[92%] sm:max-w-[80%] md:max-w-[70%] ${
                    isMine ? "flex-row-reverse" : "flex-row"
                  }`}
                >
                  {/* Message Bubble */}
                  <div
                    onTouchStart={() => handleTouchStart(messageKey)}
                    onTouchEnd={handleTouchEnd}
                    onTouchCancel={handleTouchEnd}
                    style={{ wordBreak: "break-word" }}
                    className={`relative px-4 py-2.5 text-[14px] sm:text-[14.5px] leading-relaxed transition-all ${
                      isUnsent
                        ? "bg-cream-100 text-plum-400 border border-border-subtle rounded-3xl italic text-xs"
                        : isChaos
                        ? "bg-white text-plum-900 border-2 border-purple-200/80 rounded-3xl shadow-sweet-lg font-normal"
                        : isMine
                        ? "bg-gradient-to-r from-chatora-pink via-[#FF7E9C] to-chatora-peach text-white rounded-3xl rounded-tr-sm shadow-sweet-pink font-medium"
                        : "bg-white text-plum-900 border border-border-subtle rounded-3xl rounded-tl-sm shadow-sweet-sm font-normal"
                    }`}
                  >
                    {/* Quoted Reply Section if replying to another message */}
                    {message.replyTo && (
                      <div
                        role="button"
                        tabIndex={0}
                        onClick={(e) => {
                          e.stopPropagation();
                          const targetId =
                            message.replyTo._id || message.replyTo.id;
                          if (targetId) handleScrollToMessage(targetId);
                        }}
                        onKeyDown={(e) => {
                          if (e.key === "Enter" || e.key === " ") {
                            e.preventDefault();
                            const targetId =
                              message.replyTo._id || message.replyTo.id;
                            if (targetId) handleScrollToMessage(targetId);
                          }
                        }}
                        title="Click to jump to replied message"
                        aria-label="Jump to replied message"
                        className={`mb-2 px-3 py-1.5 rounded-2xl border cursor-pointer transition-all select-none text-left ${
                          isMine && !isChaos
                            ? "bg-black/15 hover:bg-black/25 border-white/20 text-white"
                            : "bg-cream-50 hover:bg-cream-100 border-border-subtle text-plum-800"
                        }`}
                      >
                        <div className="flex items-center gap-1.5 text-[11px] font-bold mb-0.5 opacity-90">
                          <span>↩</span>
                          <span className="truncate">
                            {getQuoteSenderName(message.replyTo)}
                          </span>
                        </div>
                        <p
                          className={`text-xs truncate max-w-[220px] sm:max-w-xs md:max-w-sm ${
                            message.replyTo.isUnsent ||
                            message.replyTo.isDeletedForMe
                              ? "italic opacity-70"
                              : "opacity-95"
                          }`}
                        >
                          {getQuoteContent(message.replyTo)}
                        </p>
                      </div>
                    )}

                    {isUnsent ? (
                      <p className="italic text-xs text-plum-400 flex items-center gap-1.5 py-0.5 select-none font-medium">
                        <span className="text-sm">🚫</span>
                        <span>Message unsent</span>
                      </p>
                    ) : (
                      renderBubbleContent(message, isMine)
                    )}
                  </div>

                  {/* Actions Trigger Button */}
                  <div className="relative">
                    <button
                      type="button"
                      onClick={() =>
                        setActiveMenuId(isMenuOpen ? null : messageKey)
                      }
                      className={`w-8 h-8 flex items-center justify-center p-1.5 rounded-xl text-plum-500 hover:text-plum-900 hover:bg-cream-200 transition-all ${
                        isMenuOpen
                          ? "opacity-100 bg-cream-200"
                          : "opacity-80 md:opacity-0 group-hover:opacity-100 focus:opacity-100"
                      }`}
                      title="Message options"
                      aria-label="Message options"
                    >
                      <svg
                        xmlns="http://www.w3.org/2000/svg"
                        viewBox="0 0 20 20"
                        fill="currentColor"
                        className="w-4 h-4"
                      >
                        <path d="M10 3a1.5 1.5 0 1 1 0 3 1.5 1.5 0 0 1 0-3ZM10 8.5a1.5 1.5 0 1 1 0 3 1.5 1.5 0 0 1 0-3ZM11.5 15.5a1.5 1.5 0 1 0-3 0 1.5 1.5 0 0 1 0-3Z" />
                      </svg>
                    </button>

                    {/* Dropdown Menu */}
                    {isMenuOpen && (
                      <div
                        className={`absolute top-8 ${
                          isMine ? "right-0" : "left-0"
                        } w-36 bg-white border border-border-subtle rounded-2xl shadow-sweet-lg py-1.5 z-40 text-xs animate-in fade-in zoom-in-95 duration-100`}
                      >
                        {!isUnsent && (
                          <button
                            type="button"
                            onClick={() => {
                              setActiveMenuId(null);
                              if (onReply) onReply(message);
                            }}
                            className="w-[calc(100%-8px)] mx-1 text-left px-3 py-1.5 hover:bg-cream-100 text-plum-800 hover:text-plum-950 flex items-center gap-2 transition-colors rounded-xl font-medium"
                          >
                            <span className="text-sm">↩</span>
                            Reply
                          </button>
                        )}

                        {isMine && !isUnsent && (
                          <button
                            type="button"
                            onClick={() => {
                              setActiveMenuId(null);
                              setUnsendTarget(message);
                            }}
                            className="w-[calc(100%-8px)] mx-1 text-left px-3 py-1.5 hover:bg-amber-50 text-amber-600 hover:text-amber-700 flex items-center gap-2 transition-colors rounded-xl font-medium"
                          >
                            <span className="text-sm">↺</span>
                            Unsend
                          </button>
                        )}

                        <button
                          type="button"
                          onClick={() => {
                            setActiveMenuId(null);
                            setDeleteTarget(message);
                          }}
                          className="w-[calc(100%-8px)] mx-1 text-left px-3 py-1.5 hover:bg-rose-50 text-rose-500 hover:text-rose-600 flex items-center gap-2 transition-colors rounded-xl font-bold"
                        >
                          <span className="text-sm">🗑</span>
                          Delete
                        </button>
                      </div>
                    )}
                  </div>
                </div>

                {timeStr && (
                  <span className="text-[11px] text-plum-500 mt-1 px-1 font-semibold flex items-center gap-1">
                    <span>{timeStr}</span>
                    {isMine && !isUnsent && (
                      <span
                        className="text-chatora-pink text-xs leading-none font-extrabold select-none"
                        title="Delivered"
                        aria-label="Delivered"
                      >
                        ✓✓
                      </span>
                    )}
                  </span>
                )}
              </div>
            );
          })}
          {/* Scroll Anchor */}
          <div ref={messagesEndRef} className="h-4 flex-shrink-0" />
        </div>
      )}

      {hasActiveChat && (!messages || !messages.length) && (
        <div className="flex flex-col items-center justify-center h-full my-auto text-center px-4 select-none">
          <div className="w-16 h-16 rounded-3xl bg-white border border-chatora-pink/20 flex items-center justify-center mb-4 text-3xl shadow-sweet-pink">
            💬✨
          </div>
          <h3 className="text-lg font-extrabold text-plum-900 mb-1">
            Start the conversation
          </h3>
          <p className="text-xs text-plum-600 max-w-xs leading-relaxed font-medium mb-4">
            Say something random. Ask something interesting. Cause a little chaos.
          </p>
          <button
            type="button"
            onClick={() => {
              if (onSayHi) onSayHi();
              const inputEl = document.getElementById("chat-message-input");
              if (inputEl) inputEl.focus();
            }}
            className="px-5 py-2.5 rounded-2xl bg-gradient-to-r from-[#FFB3C6] via-[#FFBDC7] to-[#FFCCBC] border border-chatora-pink/30 hover:shadow-sweet-pink text-plum-900 font-extrabold text-xs transition-all active:scale-95 flex items-center gap-1.5"
          >
            Say Hi 👋
          </button>
        </div>
      )}

      {/* Unsend Confirmation Modal */}
      {unsendTarget && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/30 backdrop-blur-sm select-none">
          <div className="w-full max-w-sm bg-white border border-border-subtle rounded-3xl p-6 shadow-sweet-lg text-left">
            <h3 className="text-base font-extrabold text-plum-900 mb-1.5">
              Unsend this message?
            </h3>
            <p className="text-xs text-plum-600 mb-6 leading-relaxed font-medium">
              Everyone in this chat will no longer be able to see the message.
            </p>
            <div className="flex items-center justify-end gap-2.5">
              <button
                type="button"
                onClick={() => setUnsendTarget(null)}
                className="px-4 py-2.5 rounded-2xl text-xs font-bold text-plum-700 hover:text-plum-900 bg-cream-100 hover:bg-cream-200 transition-colors"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={() => {
                  const idToUnsend = unsendTarget._id || unsendTarget.id;
                  setUnsendTarget(null);
                  if (onUnsendMessage) onUnsendMessage(idToUnsend);
                }}
                className="px-5 py-2.5 rounded-2xl text-xs font-bold text-white bg-amber-500 hover:bg-amber-600 transition-all shadow-sweet-sm active:scale-95"
              >
                Unsend ↺
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Delete For Me Confirmation Modal */}
      {deleteTarget && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/30 backdrop-blur-sm select-none">
          <div className="w-full max-w-sm bg-white border border-border-subtle rounded-3xl p-6 shadow-sweet-lg text-left">
            <h3 className="text-base font-extrabold text-plum-900 mb-1.5">
              Delete message?
            </h3>
            <p className="text-xs text-plum-600 mb-6 leading-relaxed font-medium">
              This will remove the message from your chat. Other members will still have their copy.
            </p>
            <div className="flex items-center justify-end gap-2.5">
              <button
                type="button"
                onClick={() => setDeleteTarget(null)}
                className="px-4 py-2.5 rounded-2xl text-xs font-bold text-plum-700 hover:text-plum-900 bg-cream-100 hover:bg-cream-200 transition-colors"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={() => {
                  const idToDelete = deleteTarget._id || deleteTarget.id;
                  setDeleteTarget(null);
                  if (onDeleteMessageForMe) onDeleteMessageForMe(idToDelete);
                }}
                className="px-5 py-2.5 rounded-2xl text-xs font-bold text-white bg-rose-500 hover:bg-rose-600 transition-all shadow-sweet-sm active:scale-95"
              >
                Delete 🗑
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ChatMessages;
